<script setup>
import { computed, ref, watch, nextTick } from 'vue'
import { message } from 'ant-design-vue'
import { TeamOutlined, ApartmentOutlined, SafetyCertificateOutlined, HistoryOutlined, AppstoreOutlined, ArrowLeftOutlined, SwapOutlined, ReloadOutlined, ExperimentOutlined, CheckCircleOutlined, QuestionCircleOutlined, LogoutOutlined, LockOutlined } from '@ant-design/icons-vue'
import { state, ui, currentUser, allSubjects, isAdmin, login, logout, expireSession, resetDemo, deptName, scopeLabel, effective } from './model'
import PeopleView from './components/PeopleView.vue'
import DepartmentsView from './components/DepartmentsView.vue'
import PermissionsView from './components/PermissionsView.vue'
import LoginView from './components/LoginView.vue'
import AttendancePreview from './components/AttendancePreview.vue'
import AccountSecurity from './components/AccountSecurity.vue'
const page=ref('people'),permissionEmployee=ref('e1'),switcher=ref(false),identity=ref('admin'),guide=ref(false),history=ref(false),diagnostic=ref(false),loading=ref(false),access=ref(null),accessApp=ref(null),loginView=ref(null)
const ready=computed(()=>state.session?.phase==='active'&&currentUser.value?.status==='active')
const titles={people:'人员管理',departments:'部门组织',permissions:'应用权限',workbench:'我的工作台',security:'账号安全'}
const navs=[{id:'people',label:'人员管理',sub:'人员与账号生命周期',icon:TeamOutlined},{id:'departments',label:'部门组织',sub:'组织与普通权限预设',icon:ApartmentOutlined},{id:'permissions',label:'应用权限',sub:'继承、例外与数据范围',icon:SafetyCertificateOutlined}]
watch([ready,()=>state.session?.employeeId],()=>{if(ready.value)page.value=isAdmin.value?'people':'workbench'})
async function openRecovery(){const id=currentUser.value?.id;logout();await nextTick();loginView.value?.openRecovery(id)}
function toPermissions(id){permissionEmployee.value=id;page.value='permissions'}
async function switchUser(){const result=await login(identity.value,'password');if(result.ok){switcher.value=false;if(result.firstPassword)page.value='login'}else message.error(result.error)}
async function reset(){ui.fault='none';const r=await resetDemo();if(r.ok){access.value=null;accessApp.value=null;page.value='people';message.success('合成演示已重置，请重新选择身份')}else message.error(r.error)}
function inspect(app,action='*'){const result=effective(currentUser.value,app.id,action);accessApp.value=app;access.value={...result,action:action==='*'?'进入应用':app.actions.find(a=>a.id===action)?.name}}
async function mockLoading(){loading.value=true;await new Promise(r=>setTimeout(r,900));loading.value=false}
</script>
<template>
 <a-config-provider :theme="{token:{colorPrimary:'#41745b',colorSuccess:'#47856a',borderRadius:8,fontFamily:'Inter, PingFang SC, Microsoft YaHei, system-ui, sans-serif',fontSize:14,colorText:'#243b30',colorBgLayout:'#f6f8f5'}}">
 <div class="prototype-banner"><ExperimentOutlined/><strong>交互原型</strong><span>合成数据</span><span class="banner-divider">/</span><span>尚未连接 HBOS 后端</span><b class="version-mark">IAM V1 · R4 A · v0.2</b></div>
 <header class="global-header"><div class="brand"><span class="brand-symbol">H<span></span></span><div><b>HBOS</b><small>海滨智能运营管理平台</small></div></div><span class="header-divider"></span><div class="header-context">人员与权限 <a-tag>原型评审</a-tag></div><div class="header-actions"><a-button type="text" @click="guide=true"><QuestionCircleOutlined/>演示指引</a-button><a-button @click="switcher=true"><SwapOutlined/>切换演示身份</a-button><template v-if="ready"><span class="header-user"><span class="mini-avatar">{{currentUser.name.slice(-2)}}</span>{{currentUser.name}}</span><a-button type="text" aria-label="退出演示账号" @click="logout('已退出演示账号')"><LogoutOutlined/></a-button></template></div></header>
 <div v-if="!ready" class="login-container"><a-alert v-if="ui.notice" :message="ui.notice" type="info" show-icon style="margin-bottom:16px"/><a-alert v-if="ui.error" :message="ui.error" type="error" show-icon style="margin-bottom:16px"/><LoginView ref="loginView" @logged-in="page=isAdmin?'people':'workbench'"/></div>
 <div v-else class="app-shell"><aside class="sidebar"><div class="side-label">{{isAdmin?'管理中心':'个人工作台'}}</div><template v-if="isAdmin"><button v-for="nav in navs" :key="nav.id" class="nav-button" :class="{active:page===nav.id}" @click="page=nav.id"><component :is="nav.icon"/><span>{{nav.label}}<small>{{nav.sub}}</small></span><i v-if="page===nav.id"/></button></template><template v-else><button class="nav-button" :class="{active:page==='workbench'}" @click="page='workbench'"><AppstoreOutlined/><span>我的工作台<small>资料与可用应用</small></span></button><button class="nav-button" :class="{active:page==='security'}" @click="page='security'"><LockOutlined/><span>账号安全<small>密码、找回与飞书绑定</small></span></button></template>
 <div class="side-separator"></div><button class="nav-button compact" @click="history=true"><HistoryOutlined/><span>{{isAdmin?'变更记录':'我的变更记录'}}</span></button><div class="sidebar-spacer"></div><div class="review-card"><span class="review-icon"><CheckCircleOutlined/></span><b>R4 · 身份与业务关联</b><p>Employee 为人员档案中心；后端隔离实现仍待 B 阶段授权。</p><button @click="guide=true">查看评审路径 →</button></div><div class="sidebar-footer"><i class="dot green"/>本机独立原型<span>仅使用合成演示资料</span></div></aside>
 <main class="main-content"><div class="breadcrumb"><span>HBOS</span><span>/</span><span>{{isAdmin?'管理中心':'个人'}}</span><span>/</span><b>{{titles[page]}}</b><span class="mode-label">{{isAdmin?'管理员演示视角':'员工演示视角'}}</span></div>
 <a-alert v-if="ui.error" :message="ui.error" type="error" show-icon closable @close="ui.error=''" style="margin-bottom:16px"/>
 <a-alert v-if="ui.fault==='load-failure'" message="演示数据加载失败。已有记录保持不变，请点击重试。" type="error" show-icon><template #action><a-button @click="ui.fault='none'">重试加载</a-button></template></a-alert>
 <a-skeleton v-else-if="loading" active :paragraph="{rows:12}" class="panel"/>
 <template v-else><PeopleView v-if="isAdmin&&page==='people'" @permissions="toPermissions"/><DepartmentsView v-if="isAdmin&&page==='departments'"/><PermissionsView v-if="isAdmin&&page==='permissions'" :employee-id="permissionEmployee"/>
 <template v-if="!isAdmin&&page==='workbench'"><div class="page-heading"><div><div class="kicker">MY WORKSPACE</div><h1>你好，{{currentUser.name}}</h1><p class="muted">查看个人资料与已授权的应用。飞书与密码使用同一个演示账号。</p></div><a-button @click="page='security'">账号安全 →</a-button></div><section class="panel profile-strip"><span class="avatar profile-avatar">{{currentUser.name}}</span><div><h2>{{currentUser.name}} <a-tag color="green">{{currentUser.employeeId?'员工账号':'待员工关联账号'}}</a-tag></h2><p>{{deptName(currentUser.departmentId)}} · {{currentUser.position}} · {{currentUser.code}}</p><p class="muted">{{currentUser.accountId}} · {{state.session.method==='feishu'?'模拟飞书':'演示密码'}}登录</p></div></section><a-alert v-if="!currentUser.employeeId" style="margin-top:20px" message="此账号尚未确认 Employee 关联。当前仅基础体验，不开放本人或部门考勤。" type="warning" show-icon/><AttendancePreview :employee="currentUser" :can-configure="false" style="margin-top:24px"/><div class="panel-title" style="margin-top:30px"><h2>我的应用</h2><span class="muted">权限来自主部门与个人例外</span></div><div class="application-grid"><section v-for="app in state.apps" :key="app.id" class="panel app-card" :class="{unavailable:!effective(currentUser,app.id,'*').allowed}"><div class="app-card-top"><span class="app-icon" :style="{color:app.color,background:app.color+'15'}"><AppstoreOutlined/></span><a-tag :color="effective(currentUser,app.id,'*').allowed?'green':'default'">{{effective(currentUser,app.id,'*').allowed?'可进入':'无权限'}}</a-tag></div><h2>{{app.name}}</h2><p>{{app.description}}</p><small>{{effective(currentUser,app.id,'*').source}}</small><p class="app-scope">范围：{{effective(currentUser,app.id,'*').scope.map(scopeLabel).join('、')||'无有效范围'}}</p><a-button block :type="effective(currentUser,app.id,'*').allowed?'primary':'default'" @click="inspect(app)">{{effective(currentUser,app.id,'*').allowed?'进入演示应用':'查看无权限提示'}}</a-button></section></div><p class="muted" style="margin-top:20px">管理员身份不自动得到质量签署资格。演示应用只观察权限结果，没有调用业务接口。</p></template>
 <template v-if="!isAdmin&&page==='security'"><div class="page-heading"><div><div class="kicker">ACCOUNT & SECURITY</div><h1>账号安全</h1><p class="muted">重新验证后管理自己的密码与飞书绑定。</p></div></div><section class="panel"><AccountSecurity :employee="currentUser" @recover="openRecovery"/></section></template></template>
 <footer class="content-footer"><span><i class="dot green"/>{{ui.busy?'演示保存中…':ui.notice||'演示状态保存在本机，可随时重置'}}</span><button @click="diagnostic=!diagnostic">演示工具 {{diagnostic?'−':'+'}}</button></footer>
 <div v-if="diagnostic" class="demo-tools"><span>场景模拟</span><a-select v-model:value="ui.fault" aria-label="演示异常场景" style="width:210px" :options="[{value:'none',label:'正常'},{value:'save-failure',label:'保存失败（不生效）'},{value:'conflict',label:'版本冲突（不生效）'},{value:'service-failure',label:'登录服务失败'},{value:'load-failure',label:'数据加载失败'}]"/><a-button @click="mockLoading">模拟加载中</a-button><a-button @click="expireSession">模拟会话过期</a-button><a-button @click="reset"><ReloadOutlined/>重置合成演示</a-button></div>
 </main></div>
 <div v-if="!ready" class="login-foot-tools"><a-button type="text" @click="reset"><ReloadOutlined/>重置合成演示</a-button><a-select v-model:value="ui.fault" aria-label="登录服务场景" style="width:175px" :options="[{value:'none',label:'正常演示服务'},{value:'service-failure',label:'模拟登录服务失败'},{value:'save-failure',label:'模拟本机保存失败'}]"/></div>
 <a-modal v-model:open="switcher" title="切换合成演示身份" ok-text="使用密码演示入口" cancel-text="取消" :confirm-loading="ui.busy" @ok="switchUser"><p>身份切换只影响此原型。员工身份不会显示管理页面；首次临时密码会先转入改密。</p><a-select v-model:value="identity" aria-label="选择演示身份" style="width:100%" :options="allSubjects.map(e=>({value:e.id,label:e.name+' · '+(e.id==='admin'?'管理员':e.status==='active'?'普通员工':e.status==='pending'?'待开通':'已停用')}))"/></a-modal>
 <a-drawer v-model:open="guide" title="Owner 原型评审路径" :width="530"><a-alert message="交互原型 / 合成数据 / 尚未连接 HBOS 后端" type="info" show-icon/><ol class="guide-list"><li><b>Employee 档案中心</b><p>切换演示管理员，查看未开户的沈禾与单列的非员工账号。人员详情 → 身份与业务关联，核对员工主键、字符串工号与来源标识。</p></li><li><b>企业首次飞书开户</b><p>退出后，在登录页左侧选择五种企业场景。首次开户展示一次合成临时口令；预建账号须先验证原账号归属，重复登录仍复用同一账号。</p></li><li><b>未确认员工关联</b><p>企业身份已核验、无员工档案关联时仅进入基础体验；不自动创建 Employee，不开放考勤。</p></li><li><b>考勤对象范围</b><p>应用权限 → 考勤 → 合成实例。分别查询本人、指定部门与导出预览，向本人接口注入他人员工参数观察拒绝与 total=0。</p></li><li><b>范围交集与限定禁止</b><p>应用权限中演示 self 与部门按记录求交。限定动作禁止只排除匹配对象；APP 整体禁止覆盖全部动作。</p></li><li><b>调岗与本人历史</b><p>人员详情调岗后主部门继承变化，同一 Employee 的本人历史保留；事件部门无证据时不对部门管理员开放。</p></li><li><b>本人安全与管理员职责</b><p>管理员详情不会冒充目标员工调用本人改密或换绑；员工从本人账号安全重新验证后操作。</p></li><li><b>异常与扩展</b><p>演示工具查看加载 / 保存失败 / 冲突 / 会话过期；注册设备模块仅证明合成扩展。真实后端、正式 Portal 接入和隔离验收均待 B 阶段。</p></li></ol><a-alert type="warning" message="停止于 IAM_R4_IDENTITY_CONTRACT_AND_DELTA_REVIEW_READY。Owner 批准指定 commit 前，正式开发为 PENDING_OWNER。"/></a-drawer>
 <a-drawer v-model:open="history" :title="isAdmin?'演示变更记录':'我的演示变更记录'" :width="550"><a-alert message="仅本机合成操作记录，不是正式审计日志" type="info" show-icon/><a-timeline style="margin-top:24px"><a-timeline-item v-for="l in state.logs.filter(l=>isAdmin||l.label.includes(currentUser?.name))" :key="l.id"><b>{{l.label}}</b><p class="muted">{{l.time}} · {{l.actor}}</p></a-timeline-item></a-timeline></a-drawer>
 <a-modal :open="!!access" :title="access?.allowed?accessApp?.name+' · 演示应用':'403 · 没有此应用或操作权限'" :footer="null" @cancel="access=null;accessApp=null"><template v-if="access"><a-result :status="access.allowed?'success':'403'" :title="access.allowed?'允许：'+access.action:'访问已拒绝（演示）'" :sub-title="access.reason"/><p><b>来源：</b>{{access.source}}</p><p><b>有效范围：</b>{{access.scope.map(scopeLabel).join('、')||'空范围'}}</p><div class="action-grid"><a-button v-for="a in accessApp?.actions" :key="a.id" @click="inspect(accessApp,a.id)">{{a.name}}{{a.highRisk?' · 高风险':''}}</a-button></div><p class="muted">这只验证交互与权限契约形状；真实接口、后端隔离和会话撤销均未执行。</p><a-button block @click="access=null;accessApp=null">返回工作台</a-button></template></a-modal>
 </a-config-provider>
</template>
